// Render the flag tables from data/flags.js (generated by build.py from data/flags.yaml)
const FLAG_COLUMNS = ['name', 'phonetic', 'flag'];

function flagTable(flags) {
  const table = document.createElement('table');
  table.className = 'table table-striped table-bordered table-hover table-sm';

  const headerRow = table.createTHead().insertRow();
  FLAG_COLUMNS.forEach(col => {
    const th = document.createElement('th');
    th.textContent = col.charAt(0).toUpperCase() + col.slice(1);
    headerRow.appendChild(th);
  });

  const body = table.createTBody();
  flags.forEach(flag => {
    const row = body.insertRow();
    FLAG_COLUMNS.forEach(col => {
      const cell = row.insertCell();
      if (col === 'flag') {
        const img = document.createElement('img');
        img.src = flag.flag;
        img.height = 30;
        img.alt = flag.phonetic;
        cell.appendChild(img);
      } else {
        cell.textContent = flag[col];
      }
    });
  });

  return table;
}

Object.entries(window.FLAGS).forEach(([flagType, flags]) => {
  document.getElementById(`${flagType}_flag_table`).appendChild(flagTable(flags));
});
